<template>
  <header class="header">
    <div class="container">
      <div>
        <p>{{ t("room") }} {{ room }}</p>
        <h1 class="title">{{ title }}</h1>
      </div>

      <div class="header-actions">
        <span class="sync" :class="{ online: connected }" role="status">
          <span class="sync-dot" aria-hidden="true"></span>
          {{ connected ? t("online") : t("offline") }}
        </span>
        <div class="lang-switch" role="group" :aria-label="t('language')">
          <button
            v-for="code in languages"
            :key="code"
            type="button"
            class="lang-btn"
            :class="{ active: code === lang }"
            :aria-pressed="code === lang"
            @click="setLang(code)"
          >
            {{ code.toUpperCase() }}
          </button>
        </div>
        <button type="button" class="btn-auth" @click="toggleRole">
          {{ textBtn }}
        </button>
      </div>
    </div>
    <div v-if="isDemo" class="container demo-hint">
      <p>{{ demoHint }}</p>
      <a
        v-if="!isSecondWindow"
        :href="secondWindowUrl"
        target="_blank"
        rel="noopener"
        >{{ t("openSecond") }}</a
      >
    </div>
  </header>
</template>

<script>
import { computed, ref } from "vue";
import { useStore } from "vuex";

import { logOff } from "@/service/auth";
import { watchConnection } from "@/service/database";
import { getParams, isDemoRoom } from "@/utils";
import { t, lang, setLang, languages } from "@/i18n";

export default {
  name: "Header",
  setup() {
    const store = useStore();
    const room = getParams();
    const isDemo = isDemoRoom();

    const isUser = computed(() => store.getters.GET_USER);
    const title = computed(() =>
      lang.value && isUser.value ? t("teacher") : t("student")
    );
    const textBtn = computed(() => {
      if (lang.value && isDemo && !store.state.user) {
        return isUser.value ? t("viewStudent") : t("tryTeacher");
      }
      return isUser.value ? t("logout") : t("login");
    });
    // The second window is marked so it can explain the student view
    const isSecondWindow =
      new URLSearchParams(location.search).get("view") === "student";
    const secondWindowUrl = location.pathname + "?room=demo&view=student";
    const demoHint = computed(() => {
      if (!lang.value) return "";
      if (isSecondWindow && !isUser.value) return t("demoHintStudent");
      return isUser.value ? t("demoHintTeacher") : t("demoHint");
    });

    const toggleRole = () => {
      if (isDemo && !store.state.user) {
        store.commit("SET_DEMO_TEACHER", !store.state.demoTeacher);
      } else if (isUser.value) {
        logOff();
      } else {
        store.dispatch("TOGGLE_SHOW_FORM", false);
      }
    };
    const connected = ref(false);
    watchConnection((value) => (connected.value = value));

    store.dispatch("GET_USER");
    return {
      connected,
      toggleRole,
      title,
      textBtn,
      room,
      isDemo,
      secondWindowUrl,
      isSecondWindow,
      demoHint,
      t,
      lang,
      setLang,
      languages,
    };
  },
};
</script>

